CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_breadth_project_page_v2(p_task_id text, p_page_no integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; p astra_ingestion_v1.backfill_pages_v2;
 v_row jsonb; v_day date; v_month date; v_member text; v_symbol text; v_ordinal integer:=0; v_raw numeric; v_adjusted numeric;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family<>'D03' OR lower(t.provider)<>'derived' THEN RETURN 0; END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_breadth_projected_pages_v2 WHERE task_id=t.id AND page_no=p_page_no) THEN RETURN 0; END IF;
 SELECT * INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND page_no=p_page_no;
 IF jsonb_array_length(t.scope->'member_ids')<>1 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Daily return projection requires one frozen company'; END IF;
 v_member:=t.scope#>>'{member_ids,0}';v_month:=astra_ingestion_v1.backfill_date_v2(t.scope->>'source_month');
 FOR v_row IN SELECT value FROM jsonb_array_elements(COALESCE(p.raw_body::jsonb->'rows','[]')) LOOP
  v_ordinal:=v_ordinal+1;v_day:=astra_ingestion_v1.backfill_date_v2(v_row->>'market_date');v_symbol:=v_row->>'symbol';
  IF v_row->>'member_id' IS DISTINCT FROM v_member OR v_day IS NULL OR length(COALESCE(v_symbol,''))=0
   OR v_day<'2025-09-01'::date OR v_day>'2026-07-31'::date
   OR (v_month IS NOT NULL AND date_trunc('month',v_day)::date<>v_month) THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='D03 projection member/date differs from its immutable workflow scope'; END IF;
  v_raw:=CASE WHEN jsonb_typeof(v_row#>'{values,raw_ret_1d}')='number' THEN (v_row#>>'{values,raw_ret_1d}')::numeric END;
  v_adjusted:=CASE WHEN jsonb_typeof(v_row#>'{values,adjusted_ret_1d}')='number' THEN (v_row#>>'{values,adjusted_ret_1d}')::numeric END;
  INSERT INTO astra_ingestion_v1.backfill_breadth_inputs_v2(run_id,member_id,market_date,source_month,symbol,task_id,page_no,record_ordinal,
   raw_ret_1d,adjusted_ret_1d,raw_null_reason,adjusted_null_reason,formula_version,body_sha256,source_committed_at,identity_input_attribution)
  VALUES(t.run_id,v_member,v_day,date_trunc('month',v_day)::date,v_symbol,t.id,p.page_no,v_ordinal,v_raw,v_adjusted,
   CASE WHEN v_raw IS NULL THEN COALESCE(v_row#>>'{null_reasons,raw_ret_1d}','MISSING_OR_NON_NUMERIC_D03_INPUT') END,
   CASE WHEN v_adjusted IS NULL THEN COALESCE(v_row#>>'{null_reasons,adjusted_ret_1d}','MISSING_OR_NON_NUMERIC_D03_INPUT') END,
   COALESCE(v_row->>'formula_version',p.adapter_version),p.body_sha256,p.committed_at,v_row->'identity_input_attribution');
 END LOOP;
 IF v_ordinal<>p.record_count THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='D03 compact projection count differs from retained receipt'; END IF;
 INSERT INTO astra_ingestion_v1.backfill_breadth_projected_pages_v2(task_id,page_no,run_id,source_month,body_sha256,projected_records)
 VALUES(t.id,p.page_no,t.run_id,v_month,p.body_sha256,v_ordinal);
 RETURN v_ordinal;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_admit_page_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '12s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;r astra_ingestion_v1.backfill_runs_v2;e astra_ingestion_v1.backfill_contract_enumeration_v2;
 rows jsonb;syms jsonb;scope jsonb;child_id text;grp integer;children integer:=0;linked integer;unlinked integer;
 a timestamptz:='2025-09-01T00:00:00-04:00';b timestamptz:='2026-07-31T23:59:59-04:00';
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=t.run_id;
 IF r.status<>'ACTIVE' OR r.fence<>t.run_fence THEN RETURN jsonb_build_object('state','RUN_FENCE_NOT_ACTIVE');END IF;
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_state_v2 WHERE run_id=t.run_id AND seed_complete) THEN RETURN jsonb_build_object('state','RETAINED_CHILD_RECONCILIATION_PENDING');END IF;
 SELECT * INTO STRICT e FROM astra_ingestion_v1.backfill_contract_enumeration_v2 WHERE task_id=p_task AND page_no=p_page FOR UPDATE;
 IF e.processed_at IS NOT NULL THEN RETURN jsonb_build_object('state','ALREADY_LINKED');END IF;
 IF t.kind<>'alpaca_option_contracts' OR NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=p_task AND page_no=p_page) THEN RETURN jsonb_build_object('state','INDEPENDENT_READBACK_PENDING');END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('ordinal',x.record_ordinal,'symbol',x.source_row->>'symbol','underlying',x.source_row->>'underlying_symbol',
  'eligible',COALESCE(x.source_row->>'symbol' ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' AND (t.scope->'symbols') ? (x.source_row->>'underlying_symbol'),false))),'[]') INTO rows
 FROM astra_ingestion_v1.backfill_page_rows_v2(t.id,p_page) x;
 FOR syms,grp IN
  SELECT jsonb_agg(symbol ORDER BY symbol),g FROM(SELECT symbol,((row_number() OVER(ORDER BY symbol)-1)/100)::int g FROM(
   SELECT DISTINCT x->>'symbol' symbol FROM jsonb_array_elements(rows) x WHERE x->'eligible'='true'::jsonb
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_work_v2 w WHERE w.run_id=t.run_id AND w.work_key=astra_ingestion_v1.backfill_contract_key_v2(x->>'symbol',a,b,'opra','1Day'))
  ) unique_symbols) numbered GROUP BY g
 LOOP
  scope:=jsonb_build_object('symbols',syms,'member_ids',t.scope->'member_ids','start','2025-09-01T00:00:00-04:00','end','2026-07-31T23:59:59-04:00',
   'identity_status','PROVIDER_CONTRACT_UNDERLYING_LINK','enumeration_parent',t.id,'contract_registry_version','fixed3000-contract-work-v2');
  child_id:='backfill-contract-'||encode(sha256(convert_to(jsonb_build_array(t.run_id,syms,extract(epoch FROM a),extract(epoch FROM b),'opra','1Day')::text,'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
  VALUES(child_id,t.run_id,'CTX02','Alpaca','alpaca_option_bars',scope,t.priority+1,t.run_fence);
  children:=children+1;
 END LOOP;
 INSERT INTO astra_ingestion_v1.backfill_contract_parent_links_v2(run_id,parent_task_id,page_no,record_ordinal,contract_symbol,underlying_symbol,work_key,task_at_admission)
 SELECT t.run_id,t.id,p_page,(x->>'ordinal')::bigint,x->>'symbol',x->>'underlying',w.work_key,w.canonical_task_id
 FROM jsonb_array_elements(rows) x JOIN astra_ingestion_v1.backfill_contract_work_v2 w
  ON w.run_id=t.run_id AND w.work_key=astra_ingestion_v1.backfill_contract_key_v2(x->>'symbol',a,b,'opra','1Day') WHERE x->'eligible'='true'::jsonb ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS linked=ROW_COUNT;
 SELECT count(*) INTO unlinked FROM jsonb_array_elements(rows) x WHERE x->'eligible'<>'true'::jsonb;
 UPDATE astra_ingestion_v1.backfill_contract_enumeration_v2 SET processed_at=clock_timestamp(),linked_contracts=linked,unlinked_source_contracts=unlinked WHERE task_id=t.id AND page_no=p_page;
 UPDATE astra_ingestion_v1.backfill_contract_state_v2 SET parent_contract_links=parent_contract_links+linked,new_children_created=new_children_created+children,
  enumeration_pages_processed=enumeration_pages_processed+1,unlinked_source_contracts=unlinked_source_contracts+unlinked WHERE run_id=t.run_id;
 RETURN jsonb_build_object('state','CONTRACT_WORK_LINKED','new_children',children,'linked_source_contracts',linked,'unlinked_source_contracts',unlinked,
  'preexisting_children_preserved',true,'historical_enumeration_completeness_certified',false);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_seed_v2(p_run text, p_limit integer DEFAULT 8)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '12s'
AS $function$
DECLARE c astra_ingestion_v1.backfill_contract_state_v2;t record;n integer:=0;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_run,706314020261099));
 INSERT INTO astra_ingestion_v1.backfill_contract_state_v2(run_id) VALUES(p_run) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT c FROM astra_ingestion_v1.backfill_contract_state_v2 WHERE run_id=p_run FOR UPDATE;
 IF c.seed_complete THEN RETURN 0;END IF;
 FOR t IN SELECT id,created_at FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=p_run AND kind='alpaca_option_bars'
  AND (created_at,id)>(c.child_created_at,c.child_id) ORDER BY created_at,id LIMIT GREATEST(1,LEAST(p_limit,16)) LOOP
  PERFORM astra_ingestion_v1.backfill_contract_register_child_v2(t.id);n:=n+1;
  UPDATE astra_ingestion_v1.backfill_contract_state_v2 SET child_created_at=t.created_at,child_id=t.id WHERE run_id=p_run;
 END LOOP;
 UPDATE astra_ingestion_v1.backfill_contract_state_v2 st SET seed_complete=true WHERE st.run_id=p_run
  AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 pending WHERE pending.run_id=p_run AND pending.kind='alpaca_option_bars' AND (pending.created_at,pending.id)>(st.child_created_at,st.child_id));
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_discover_member_v2(p_run text, p_member text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE m astra_ingestion_v1.backfill_members_v2;r astra_ingestion_v1.backfill_runs_v2;x record;meta jsonb;v_id text;n integer:=0;
 state astra_ingestion_v1.backfill_identity_discovered_members_v2;seen integer:=0;last_day date;last_source text;more boolean;
BEGIN
 SELECT * INTO STRICT m FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=p_run AND member_id=p_member;
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=p_run FOR UPDATE;
 IF r.status<>'ACTIVE' THEN RETURN 0; END IF;
 INSERT INTO astra_ingestion_v1.backfill_identity_discovered_members_v2(run_id,member_id,discovered_sources) VALUES(p_run,p_member,0) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT state FROM astra_ingestion_v1.backfill_identity_discovered_members_v2 WHERE run_id=p_run AND member_id=p_member FOR UPDATE;
 IF state.complete THEN RETURN 0; END IF;
 last_day:=state.after_day;last_source:=state.after_source_id;
 FOR x IN SELECT DISTINCT o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}') source_id
  FROM reference.massive_security_master_observation_v1 o
  WHERE o.requested_as_of BETWEEN '2025-06-05'::date AND '2026-07-31'::date
   AND o.source_route='market_data_remediation_20261008_v1.massive_native_listing_pages_v1'
   AND (o.ticker=m.anchor_ticker OR (o.composite_figi=m.anchor->>'anchor_composite_figi' AND o.share_class_figi=m.anchor->>'anchor_share_class_figi'))
   AND o.raw_payload#>>'{_remediation_acquisition,source_id}' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   AND (o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}'))>(state.after_day,state.after_source_id)
  ORDER BY o.requested_as_of,source_id LIMIT 128
 LOOP
  seen:=seen+1;last_day:=x.requested_as_of;last_source:=x.source_id;
  meta:=astra_ingestion_v1.backfill_identity_source_meta_v2(x.source_id::uuid,x.requested_as_of,false);
  IF meta->>'state'<>'RETAINED_SOURCE_READY' THEN
   INSERT INTO astra_ingestion_v1.backfill_identity_discovery_gaps_v2(run_id,member_id,market_date,source_id,reason,evidence)
   VALUES(p_run,p_member,x.requested_as_of,x.source_id::uuid,COALESCE(meta->>'reason','RETAINED_SOURCE_UNVERIFIABLE'),meta) ON CONFLICT DO NOTHING;
   CONTINUE; END IF;
  v_id:='backfill-identity-source-'||encode(sha256(convert_to(p_run||':'||x.source_id,'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
  VALUES(v_id,p_run,'REF01','REUSE','retained_identity',jsonb_build_object('identity_source_id',x.source_id,
   'expected_source_sha256',meta->>'source_sha256','reference_date',x.requested_as_of,'cohort_sha256',r.cohort_sha256,
   'shared_cohort_reference',true,'member_ids','[]'::jsonb,'plan_static',false,'governing_date','REFERENCE_AS_OF'),15,r.fence)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO astra_ingestion_v1.backfill_identity_source_members_v2 VALUES(p_run,p_member,v_id) ON CONFLICT DO NOTHING;
  n:=n+1;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM reference.massive_security_master_observation_v1 o
  WHERE o.requested_as_of BETWEEN '2025-06-05'::date AND '2026-07-31'::date
   AND o.source_route='market_data_remediation_20261008_v1.massive_native_listing_pages_v1'
   AND (o.ticker=m.anchor_ticker OR (o.composite_figi=m.anchor->>'anchor_composite_figi' AND o.share_class_figi=m.anchor->>'anchor_share_class_figi'))
   AND o.raw_payload#>>'{_remediation_acquisition,source_id}' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   AND (o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}'))>(last_day,last_source)) INTO more;
 UPDATE astra_ingestion_v1.backfill_identity_discovered_members_v2 SET discovered_sources=discovered_sources+n,observed_at=clock_timestamp(),
  complete=NOT more,after_day=last_day,after_source_id=last_source WHERE run_id=p_run AND member_id=p_member;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_minute_account_v2(p_task_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; parent astra_ingestion_v1.backfill_tasks_v2;
 v astra_ingestion_v1.backfill_readbacks_v2; v_asset text; v_member text; v_symbol text;
 v_complete boolean; v_max integer; v_added integer;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family NOT IN('P01','P02') OR t.kind NOT IN('retained_reuse','alpaca_stock_bars')
 OR COALESCE(t.scope->>'timeframe','1Min')<>'1Min' THEN RETURN jsonb_build_object('state','NOT_MINUTE_SOURCE'); END IF;
 IF jsonb_array_length(COALESCE(t.scope->'member_ids','[]'))<>1 THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute accounting requires an explicit single fixed member'; END IF;
 v_member:=t.scope#>>'{member_ids,0}';v_symbol:=COALESCE(t.scope->>'symbol',t.scope#>>'{symbols,0}');
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=t.run_id AND m.member_id=v_member AND m.anchor_ticker=v_symbol) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute source differs from its frozen provider anchor'; END IF;
 IF t.scope ? 'reuse_parent' THEN SELECT * INTO STRICT parent FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=t.scope->>'reuse_parent'; END IF;
 v_asset:=COALESCE(t.scope->>'alpaca_asset_id',parent.scope->>'alpaca_asset_id',
  (SELECT CASE WHEN count(*)=1 THEN min(i.alpaca_asset_id::text) END FROM reference.alpaca_fixed_window_instruments_v1 i WHERE i.symbol=v_symbol),'ANCHOR_SYMBOL:'||v_symbol);
 SELECT max(page_no) INTO v_max FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=t.id;
 IF v_max IS NULL THEN RETURN jsonb_build_object('state','READBACK_REQUIRED'); END IF;
 IF t.kind='retained_reuse' THEN
  SELECT * INTO STRICT v FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=t.id AND page_no=0;
  IF v.retained_source_verification->'passed' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained session counts require successful source verification'; END IF;
  INSERT INTO astra_ingestion_v1.backfill_minute_sessions_v2
   (run_id,task_id,member_id,symbol,asset_key,market_date,source_type,query_complete,
    raw_rth,raw_pre,raw_post,qualified_rth,qualified_pre,qualified_post,usable_rth,usable_pre,usable_post,last_verified_page,source_verified_at)
  SELECT t.run_id,t.id,v_member,v_symbol,v_asset,(e->>'market_date')::date,'RETAINED',false,
   (e->>'rth_count')::bigint,(e->>'pre_count')::bigint,(e->>'post_count')::bigint,
   (e->>'qualified_rth_count')::bigint,(e->>'qualified_pre_count')::bigint,(e->>'qualified_post_count')::bigint,
   (e->>'usable_rth_count')::bigint,(e->>'usable_pre_count')::bigint,(e->>'usable_post_count')::bigint,v_max,v.verified_at
  FROM jsonb_array_elements(v.retained_source_verification->'session_coverage') e
  ON CONFLICT(task_id,market_date) DO NOTHING;
 ELSE
  IF (t.scope->>'end')::timestamptz-(t.scope->>'start')::timestamptz>interval '32 days' THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute accounting unit must fit32 days'; END IF;
  SELECT t.status IN('INGESTED','NO_DATA_RETURNED','IDENTITY_OR_QUALITY_UNRESOLVED')
   AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 p WHERE p.task_id=t.id AND p.cursor_out IS NULL
     AND p.raw_body::jsonb ? 'next_page_token' AND p.raw_body::jsonb->'next_page_token'='null'::jsonb)
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 p WHERE p.task_id=t.id
     AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 b WHERE b.task_id=p.task_id AND b.page_no=p.page_no)) INTO v_complete;
  WITH bars AS MATERIALIZED (
   SELECT x.symbol,x.market_date,x.session,astra_ingestion_v1.backfill_stamp_v2(x.source_row->>'t') stamp,
    count(DISTINCT x.source_row)=1 AND bool_and(astra_ingestion_v1.backfill_bar_usable_v2(x.source_row)) usable
   FROM astra_ingestion_v1.backfill_pages_v2 p JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
   CROSS JOIN LATERAL astra_ingestion_v1.backfill_page_rows_v2(p.task_id,p.page_no) x
   WHERE p.task_id=t.id AND x.symbol=v_symbol AND x.session IN('RTH','PRE','POST')
   GROUP BY x.symbol,x.market_date,x.session,astra_ingestion_v1.backfill_stamp_v2(x.source_row->>'t')
  ), days AS (
   SELECT DISTINCT (e->>'date')::date market_date FROM jsonb_array_elements(COALESCE(t.scope->'calendar','[]')) e
   WHERE (e->>'date')::date BETWEEN ((t.scope->>'start')::timestamptz AT TIME ZONE 'America/New_York')::date
    AND ((t.scope->>'end')::timestamptz AT TIME ZONE 'America/New_York')::date
  )
  INSERT INTO astra_ingestion_v1.backfill_minute_sessions_v2
   (run_id,task_id,member_id,symbol,asset_key,market_date,source_type,query_complete,
    raw_rth,raw_pre,raw_post,qualified_rth,qualified_pre,qualified_post,usable_rth,usable_pre,usable_post,last_verified_page,source_verified_at)
  SELECT t.run_id,t.id,v_member,v_symbol,v_asset,d.market_date,'ACQUIRED',v_complete
   AND (t.scope->>'start')::timestamptz<=((d.market_date+time '04:00') AT TIME ZONE 'America/New_York')
   AND (t.scope->>'end')::timestamptz>=((d.market_date+time '19:59') AT TIME ZONE 'America/New_York'),
   count(*) FILTER(WHERE b.session='RTH'),count(*) FILTER(WHERE b.session='PRE'),count(*) FILTER(WHERE b.session='POST'),
   count(*) FILTER(WHERE b.session='RTH'),count(*) FILTER(WHERE b.session='PRE'),count(*) FILTER(WHERE b.session='POST'),
   count(*) FILTER(WHERE b.session='RTH' AND b.usable),count(*) FILTER(WHERE b.session='PRE' AND b.usable),count(*) FILTER(WHERE b.session='POST' AND b.usable),
   v_max,clock_timestamp() FROM days d LEFT JOIN bars b ON b.market_date=d.market_date GROUP BY d.market_date
  ON CONFLICT(task_id,market_date) DO UPDATE SET query_complete=EXCLUDED.query_complete,
   raw_rth=EXCLUDED.raw_rth,raw_pre=EXCLUDED.raw_pre,raw_post=EXCLUDED.raw_post,
   qualified_rth=EXCLUDED.qualified_rth,qualified_pre=EXCLUDED.qualified_pre,qualified_post=EXCLUDED.qualified_post,
   usable_rth=EXCLUDED.usable_rth,usable_pre=EXCLUDED.usable_pre,usable_post=EXCLUDED.usable_post,
   last_verified_page=EXCLUDED.last_verified_page,source_verified_at=EXCLUDED.source_verified_at;
 END IF;
 GET DIAGNOSTICS v_added=ROW_COUNT;
 INSERT INTO astra_ingestion_v1.backfill_minute_projection_v2(task_id,last_verified_page) VALUES(t.id,v_max)
 ON CONFLICT(task_id) DO UPDATE SET last_verified_page=EXCLUDED.last_verified_page,projected_at=clock_timestamp();
 RETURN jsonb_build_object('state','MINUTE_SESSIONS_PROJECTED','task_id',t.id,'sessions',v_added,'last_verified_page',v_max);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_nonminute_project_page_v2(p_task_id text, p_page_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;p astra_ingestion_v1.backfill_pages_v2;
 role text;variant text;spec jsonb; v_inserted integer;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family IN('P01','P02','D01','REF03') THEN RETURN jsonb_build_object('state','SEPARATE_MINUTE_OR_AUDIT_ACCOUNTING'); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_nonminute_pages_v2 WHERE task_id=t.id AND page_no=p_page_no) THEN RETURN jsonb_build_object('state','ALREADY_PROJECTED'); END IF;
 SELECT pg.* INTO p FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
  WHERE pg.task_id=t.id AND pg.page_no=p_page_no AND pg.body_sha256=b.body_sha256 AND b.body_sha256=b.readback_sha256 AND pg.record_count=b.actual_records;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Non-minute projection requires independently verified immutable page evidence'; END IF;
 role:=CASE WHEN lower(t.provider)='reuse' OR p.raw_body::jsonb#>>'{rows,0,record_type}' IN('RETAINED_REFERENCE_SOURCE_POINTER','DERIVED_RETAINED_SOURCE_POINTER','RETAINED_SOURCE_POINTER') THEN 'POINTER'
  WHEN lower(t.provider)='derived' THEN 'DERIVED' ELSE 'SOURCE' END;
 variant:=CASE WHEN t.kind='alpaca_stock_bars' AND t.scope->>'timeframe'='1Day' THEN 'ALPACA_1DAY_'||upper(COALESCE(t.scope->>'adjustment','raw'))
  WHEN role='DERIVED' THEN t.family||'_DERIVED_OUTPUT' ELSE t.kind END;
 spec:=CASE WHEN role='POINTER' THEN '{}'::jsonb ELSE astra_ingestion_v1.backfill_nonminute_field_spec_v2(t.family,t.kind) END;
 WITH rows AS MATERIALIZED(
  SELECT x.source_row,COALESCE(x.market_date,CASE WHEN t.kind='massive_reference' THEN astra_ingestion_v1.backfill_date_v2(t.scope->>'asof') END) d
  FROM astra_ingestion_v1.backfill_page_rows_v2(t.id,p_page_no) x
 ), dated AS MATERIALIZED(
  SELECT *,CASE WHEN d BETWEEN '2025-09-01'::date AND '2026-07-31'::date THEN 'TARGET'
   WHEN d<'2025-09-01'::date THEN 'SUPPORT' WHEN d>'2026-07-31'::date THEN 'AFTER_TARGET' ELSE 'UNKNOWN_DATE' END period FROM rows
 ), fields AS MATERIALIZED(
  SELECT d.period,f.key field,f.value datatype,v.value,
   astra_ingestion_v1.backfill_nonminute_field_reason_v2(v.value,f.value,
    COALESCE(d.source_row#>>ARRAY['null_reasons',f.key],
     CASE WHEN f.key='publication_time' AND (v.value IS NULL OR v.value='null'::jsonb) THEN 'PUBLICATION_TIMESTAMP_NOT_SUPPLIED'
      WHEN f.key='eligible_company_count' AND (v.value IS NULL OR v.value='null'::jsonb) THEN 'ELIGIBLE_COMPANY_DENOMINATOR_UNKNOWN' END)) reason
  FROM dated d CROSS JOIN jsonb_each_text(spec) f
  CROSS JOIN LATERAL(SELECT astra_ingestion_v1.backfill_nonminute_field_value_v2(d.source_row,role,f.key) value) v
 ), counts AS(
  SELECT period,field,datatype,(value IS NOT NULL AND value<>'null'::jsonb) nonnull,reason,count(*) n
  FROM fields GROUP BY period,field,datatype,(value IS NOT NULL AND value<>'null'::jsonb),reason
 )
 INSERT INTO astra_ingestion_v1.backfill_nonminute_pages_v2(task_id,page_no,run_id,family,kind,provider,observation_role,source_variant,body_sha256,physical_records,
  target_records,support_records,after_target_records,unknown_date_records,target_first_date,target_last_date,support_first_date,support_last_date,after_target_first_date,after_target_last_date,
  page_has_quality_findings,field_counts)
 SELECT t.id,p_page_no,t.run_id,t.family,t.kind,t.provider,role,variant,p.body_sha256,count(*),
  count(*) FILTER(WHERE period='TARGET'),count(*) FILTER(WHERE period='SUPPORT'),count(*) FILTER(WHERE period='AFTER_TARGET'),count(*) FILTER(WHERE period='UNKNOWN_DATE'),
  min(d) FILTER(WHERE period='TARGET'),max(d) FILTER(WHERE period='TARGET'),min(d) FILTER(WHERE period='SUPPORT'),max(d) FILTER(WHERE period='SUPPORT'),min(d) FILTER(WHERE period='AFTER_TARGET'),max(d) FILTER(WHERE period='AFTER_TARGET'),
  jsonb_array_length(p.quality)>0,
  (SELECT COALESCE(jsonb_agg(jsonb_build_object('period',period,'field',field,'datatype',datatype,'nonnull',nonnull,'reason',reason,'records',n) ORDER BY period,field,reason),'[]') FROM counts)
 FROM dated ON CONFLICT(task_id,page_no) DO NOTHING;
 GET DIAGNOSTICS v_inserted=ROW_COUNT;
 RETURN jsonb_build_object('state','NONMINUTE_PAGE_PROJECTED','task_id',t.id,'page_no',p_page_no,'inserted',v_inserted);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_s02_seed_v2(p_run text, p_limit integer DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE r astra_ingestion_v1.backfill_runs_v2;c astra_ingestion_v1.backfill_s02_seed_cursor_v2;p record;members jsonb;symbols jsonb;scope jsonb;key text;n integer:=0;
BEGIN
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=p_run;
 IF r.status<>'ACTIVE' OR r.cohort_sha256<>'2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR r.target_start<>'2025-09-01'::date OR r.target_end<>'2026-07-31'::date THEN RETURN 0; END IF;
 INSERT INTO astra_ingestion_v1.backfill_s02_seed_cursor_v2(run_id) VALUES(r.id) ON CONFLICT DO NOTHING;
 SELECT * INTO c FROM astra_ingestion_v1.backfill_s02_seed_cursor_v2 WHERE run_id=r.id FOR UPDATE;
 FOR p IN SELECT * FROM population_top3000_202608_202609_v1.massive_shortinterest_page_v1
  WHERE archive_key='massive-archive:S02:c1ed3ed6aa5bad110f122c2459ba27f6daa14a7ac484363d4915c0fc9ddb1f88'
   AND page_number>=c.next_page AND page_number<=45 ORDER BY page_number LIMIT GREATEST(1,LEAST(p_limit,8)) LOOP
  WITH anchors AS(SELECT anchor_ticker,min(member_id) member_id FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id GROUP BY anchor_ticker HAVING count(*)=1)
  SELECT COALESCE(jsonb_agg(DISTINCT m.member_id ORDER BY m.member_id),'[]'),COALESCE(jsonb_agg(DISTINCT m.anchor_ticker ORDER BY m.anchor_ticker),'[]') INTO members,symbols
   FROM population_top3000_202608_202609_v1.massive_shortinterest_record_v1 q JOIN anchors m ON m.anchor_ticker=q.raw_record->>'ticker'
   WHERE q.archive_key=p.archive_key AND q.page_number=p.page_number AND astra_ingestion_v1.backfill_date_v2(q.raw_record->>'settlement_date') BETWEEN '2026-07-15'::date AND '2026-07-31'::date;
  IF jsonb_array_length(members)>0 THEN
   scope:=jsonb_build_object('archive_key',p.archive_key,'archive_page',p.page_number,'source_id',p.source_id,'expected_source_sha256',p.source_sha256,
    'settlement_start','2026-07-15','settlement_end','2026-07-31','member_ids',members,'symbols',symbols,'preserve_provider_acquisition',true,'retained_overlay',true);
   key:='backfill-retained-s02-'||encode(sha256(convert_to(r.id||':'||p.archive_key||':'||p.page_number::text||':'||p.source_sha256,'UTF8')),'hex');
   INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
    VALUES(key,r.id,'S02','REUSE','retained_massive_archive',scope,80,r.fence) ON CONFLICT DO NOTHING;n:=n+1;
  END IF;
  UPDATE astra_ingestion_v1.backfill_s02_seed_cursor_v2 SET next_page=p.page_number+1 WHERE run_id=r.id;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_shared_project_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '12s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;p astra_ingestion_v1.backfill_pages_v2;keys jsonb;old_summary jsonb;families text[];
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 IF t.kind NOT IN('alpaca_news','massive_news','alpaca_actions','massive_dividends','massive_splits','alpaca_option_contracts','alpaca_option_bars') THEN RETURN jsonb_build_object('state','SEPARATE_FAMILY');END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_shared_pages_v2 WHERE task_id=p_task AND page_no=p_page) THEN RETURN jsonb_build_object('state','ALREADY_PROJECTED');END IF;
 SELECT pg.* INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
  WHERE pg.task_id=p_task AND pg.page_no=p_page AND pg.body_sha256=b.body_sha256 AND b.body_sha256=b.readback_sha256 AND pg.record_count=b.actual_records;
 WITH rows AS MATERIALIZED(SELECT x.record_ordinal,astra_ingestion_v1.backfill_shared_meta_v2(t.provider,t.kind,x.record_group,x.symbol,x.source_row) m
  FROM astra_ingestion_v1.backfill_page_rows_v2(p_task,p_page) x),
 versions AS(INSERT INTO astra_ingestion_v1.backfill_shared_versions_v2
  SELECT DISTINCT ON(m->>'record_key',m->>'row_sha256') t.run_id,m->>'record_key',m->>'row_sha256',m->>'provider',m->>'record_type',m->>'kind',m->>'record_group',
   m->>'provider_record_id',m->>'identity_basis',m->>'symbol',(m->>'market_date')::date,m->'date_axes',m->>'primary_date_field',
   (m->>'version_timestamp')::timestamptz,m->'field_states',ARRAY(SELECT jsonb_array_elements_text(m->'delivery_families')),t.id,p_page,record_ordinal
  FROM rows ORDER BY m->>'record_key',m->>'row_sha256',record_ordinal ON CONFLICT DO NOTHING RETURNING record_key),
 occurrences AS(INSERT INTO astra_ingestion_v1.backfill_shared_occurrences_v2
  SELECT t.run_id,m->>'record_key',m->>'row_sha256',t.id,p_page,record_ordinal FROM rows ON CONFLICT DO NOTHING RETURNING record_key),
 links AS(INSERT INTO astra_ingestion_v1.backfill_shared_version_links_v2
  SELECT DISTINCT t.run_id,m->>'record_key',m->>'row_sha256',l->>'symbol',l->>'role' FROM rows CROSS JOIN LATERAL jsonb_array_elements(m->'links') l
  ON CONFLICT DO NOTHING RETURNING record_key)
 SELECT COALESCE(jsonb_agg(DISTINCT m->>'record_key'),'[]') INTO keys FROM rows;
 old_summary:=astra_ingestion_v1.backfill_shared_summary_v2(t.run_id,keys);
 PERFORM astra_ingestion_v1.backfill_shared_refresh_v2(t.run_id,keys);
 PERFORM astra_ingestion_v1.backfill_shared_apply_delta_v2(t.run_id,old_summary,astra_ingestion_v1.backfill_shared_summary_v2(t.run_id,keys));
 families:=CASE WHEN t.kind='alpaca_actions' THEN ARRAY['N02','N03'] ELSE ARRAY[t.family] END;
 INSERT INTO astra_ingestion_v1.backfill_shared_pages_v2(task_id,page_no,run_id,delivery_families,source_records) VALUES(t.id,p_page,t.run_id,families,p.record_count);
 RETURN jsonb_build_object('state','SHARED_RECORDS_PROJECTED','record_keys_touched',jsonb_array_length(keys),'source_occurrences',p.record_count);
END $function$
